#!/usr/bin/env python3
# -*- coding: utf-8 -*-

from __future__ import annotations

import ast
import base64
import shutil
import sys
from datetime import datetime
from pathlib import Path

SYNC_NAME = "sync_project_control.py"
VALIDATOR_NAME = "validate_project_control.py"

SYNC_BLOCK = base64.b64decode("").decode("utf-8")
VALIDATOR_BLOCK = base64.b64decode("").decode("utf-8")


def insert_before_entrypoint(text: str, block: str) -> str:
    marker = 'if __name__ == "__main__":'
    index = text.rfind(marker)

    if index < 0:
        raise RuntimeError("Script entry point was not found.")

    return (
        text[:index].rstrip()
        + "\n\n"
        + block.rstrip()
        + "\n\n"
        + text[index:]
    )


def syntax_check(text: str, filename: str) -> None:
    ast.parse(text, filename=filename)


def main() -> int:
    script_dir = Path(__file__).resolve().parent
    sync_path = script_dir / SYNC_NAME
    validator_path = script_dir / VALIDATOR_NAME

    for path in (sync_path, validator_path):
        if not path.is_file():
            print(f"ERROR: File not found: {path}", file=sys.stderr)
            return 2

    sync_original = sync_path.read_text(encoding="utf-8")
    validator_original = validator_path.read_text(encoding="utf-8")

    if "END_OF_GRAPH_ID = \"NONE\"" in sync_original:
        print("ERROR: Synchronizer Part VIII is already installed.", file=sys.stderr)
        return 3

    if "PCV-CTL-END-OF-GRAPH-VALID" in validator_original:
        print("ERROR: Validator terminal compatibility is already installed.", file=sys.stderr)
        return 4

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    sync_backup = sync_path.with_name(
        f"{sync_path.name}.bak_part8_{timestamp}"
    )
    validator_backup = validator_path.with_name(
        f"{validator_path.name}.bak_part8_{timestamp}"
    )

    sync_updated = insert_before_entrypoint(
        sync_original,
        SYNC_BLOCK,
    )
    validator_updated = insert_before_entrypoint(
        validator_original,
        VALIDATOR_BLOCK,
    )

    try:
        syntax_check(sync_updated, str(sync_path))
        syntax_check(validator_updated, str(validator_path))

        shutil.copy2(sync_path, sync_backup)
        shutil.copy2(validator_path, validator_backup)

        sync_path.write_text(sync_updated, encoding="utf-8")
        validator_path.write_text(
            validator_updated,
            encoding="utf-8",
        )

        syntax_check(
            sync_path.read_text(encoding="utf-8"),
            str(sync_path),
        )
        syntax_check(
            validator_path.read_text(encoding="utf-8"),
            str(validator_path),
        )

    except Exception as error:
        if sync_backup.is_file():
            shutil.copy2(sync_backup, sync_path)

        if validator_backup.is_file():
            shutil.copy2(validator_backup, validator_path)

        print("PATCH ROLLED BACK", file=sys.stderr)
        print(f"Reason: {error}", file=sys.stderr)
        return 5

    print("PATCH APPLIED")
    print(f"Updated : {sync_path}")
    print(f"Backup  : {sync_backup}")
    print(f"Updated : {validator_path}")
    print(f"Backup  : {validator_backup}")
    print()
    print("Part VIII installed:")
    print("- Explicit NONE end-of-graph sentinel in synchronizer")
    print("- Legacy empty terminal value compatibility")
    print("- Terminal graph verification in validator")
    print("- Next-deliverable terminal findings normalized")
    print("- Syntax validation and automatic rollback")
    print()
    print("No YAML files were modified.")
    print()
    print("Next safe command:")
    print("python -B sync_project_control.py")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
